python3 << 'PYEOF'
import json

# Read current flow
with open('SlackWeatherPipeline.flow', 'r') as f:
    flow = json.load(f)

# Read definitions from files
with open('/tmp/def_decision_full.json', 'r') as f:
    def_decision = json.load(f)
with open('/tmp/def_script_full.json', 'r') as f:
    def_script = json.load(f)
with open('/tmp/def_end_full.json', 'r') as f:
    def_end = json.load(f)

# Remove orphan http nodes from nodes[] 
orphan_ids = {'getSlackChannels1', 'getGeocoding1', 'getWeather1'}
flow['nodes'] = [n for n in flow['nodes'] if n['id'] not in orphan_ids]

# Add user-owned nodes:
# 1. parseCity script (parse city from Slack channel purpose.value)
parse_city_node = {
    "id": "parseCity",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Parse City from Address"},
    "inputs": {
        "script": "var address = $vars.getOfficeBellevueChannelInfo1.output.body.channel.purpose.value || '';\nvar parts = address.split(',');\nvar city = parts.length >= 2 ? parts[parts.length - 2].trim() : 'Bellevue';\nreturn { city: city, rawAddress: address };"
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the script",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the script fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
}

# 2. checkTemp decision
check_temp_node = {
    "id": "checkTemp",
    "type": "core.logic.decision",
    "typeVersion": "1.1",
    "display": {"label": "Temperature > 60F?"},
    "inputs": {
        "expression": "$vars.getCurrentWeather1.output.body.current_weather.temperature > 60"
    }
}

# 3. buildVerdict script - produces verdict text, referenced by end nodes
build_verdict_warm = {
    "id": "buildVerdictWarm",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Set Warm Verdict"},
    "inputs": {
        "script": "return { verdict: 'warm office today' };"
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the script",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the script fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
}

build_verdict_cold = {
    "id": "buildVerdictCold",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Set Cold Verdict"},
    "inputs": {
        "script": "return { verdict: 'cold office today' };"
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the script",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the script fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
}

# 4. End nodes with output mapping
end_warm = {
    "id": "endWarm",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End - Warm"},
    "inputs": {},
    "outputs": {
        "verdict": {
            "source": "=js:$vars.buildVerdictWarm.output.verdict"
        }
    }
}

end_cold = {
    "id": "endCold",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End - Cold"},
    "inputs": {},
    "outputs": {
        "verdict": {
            "source": "=js:$vars.buildVerdictCold.output.verdict"
        }
    }
}

# Append user-owned nodes
flow['nodes'].extend([parse_city_node, check_temp_node, build_verdict_warm, build_verdict_cold, end_warm, end_cold])

# Add edges
flow['edges'] = [
    {"id": "e-start-slackInfo", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "getOfficeBellevueChannelInfo1", "targetPort": "input"},
    {"id": "e-slackInfo-parseCity", "sourceNodeId": "getOfficeBellevueChannelInfo1", "sourcePort": "output", "targetNodeId": "parseCity", "targetPort": "input"},
    {"id": "e-parseCity-getWeather", "sourceNodeId": "parseCity", "sourcePort": "success", "targetNodeId": "getCurrentWeather1", "targetPort": "input"},
    {"id": "e-getWeather-checkTemp", "sourceNodeId": "getCurrentWeather1", "sourcePort": "output", "targetNodeId": "checkTemp", "targetPort": "input"},
    {"id": "e-checkTemp-warm", "sourceNodeId": "checkTemp", "sourcePort": "true", "targetNodeId": "buildVerdictWarm", "targetPort": "input"},
    {"id": "e-checkTemp-cold", "sourceNodeId": "checkTemp", "sourcePort": "false", "targetNodeId": "buildVerdictCold", "targetPort": "input"},
    {"id": "e-warm-endWarm", "sourceNodeId": "buildVerdictWarm", "sourcePort": "success", "targetNodeId": "endWarm", "targetPort": "input"},
    {"id": "e-cold-endCold", "sourceNodeId": "buildVerdictCold", "sourcePort": "success", "targetNodeId": "endCold", "targetPort": "input"},
]

# Remove http.v2 definition (no longer used), keep connector definitions
flow['definitions'] = [d for d in flow['definitions'] if d.get('nodeType') != 'core.action.http.v2']

# Add missing definitions (decision, script, end)
existing_types = {d['nodeType'] for d in flow['definitions']}
for defn in [def_decision, def_script, def_end]:
    if defn['nodeType'] not in existing_types:
        flow['definitions'].append(defn)
        existing_types.add(defn['nodeType'])

# Add out variable to globals
flow.setdefault('variables', {})
flow['variables'].setdefault('globals', [])
flow['variables']['globals'] = [
    {
        "id": "verdict",
        "direction": "out",
        "type": "string",
        "description": "Weather verdict for the office"
    }
]

# Clean up orphan variables.nodes entries
orphan_var_prefixes = {'getSlackChannels1.', 'getGeocoding1.', 'getWeather1.'}
flow['variables']['nodes'] = [
    v for v in flow['variables'].get('nodes', [])
    if not any(v['id'].startswith(p) for p in orphan_var_prefixes)
]

# Add variables.nodes for user-authored nodes
existing_var_ids = {v['id'] for v in flow['variables']['nodes']}
for node_id, outputs in [
    ('parseCity', ['output', 'error']),
    ('checkTemp', []),
    ('buildVerdictWarm', ['output', 'error']),
    ('buildVerdictCold', ['output', 'error']),
]:
    for out_id in outputs:
        vid = f"{node_id}.{out_id}"
        if vid not in existing_var_ids:
            flow['variables']['nodes'].append({
                "id": vid,
                "type": "object",
                "binding": {"nodeId": node_id, "outputId": out_id}
            })

# Add layout entries for new nodes
for node_id in ['parseCity', 'checkTemp', 'buildVerdictWarm', 'buildVerdictCold', 'endWarm', 'endCold']:
    if node_id not in flow['layout']['nodes']:
        flow['layout']['nodes'][node_id] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

# Remove orphan layout entries
for oid in orphan_ids:
    flow['layout']['nodes'].pop(oid, None)

with open('SlackWeatherPipeline.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print("Flow written successfully")
print("Nodes:", [n['id'] for n in flow['nodes']])
print("Edges:", len(flow['edges']))
print("Definitions:", [d['nodeType'] for d in flow['definitions']])
print("Global vars:", [v['id'] for v in flow['variables'].get('globals', [])])
PYEOF

cd /work/output/artifacts/skill-flow-slack-weather-pipeline/SlackWeatherPipeline/SlackWeatherPipeline \
  && uip maestro flow validate "SlackWeatherPipeline.flow" --output json 2>&1 | python3 -c "
import json, sys
txt = sys.stdin.read()
try:
    d = json.loads(txt)
    print('Result:', d.get('Result'))
    print('Code:', d.get('Code'))
    errors = d.get('Data', {}).get('Errors', [])
    warnings = d.get('Data', {}).get('Warnings', [])
    if errors:
        print('ERRORS:')
        for e in errors: print(' -', e)
    if warnings:
        print('WARNINGS:')
        for w in warnings: print(' -', w)
    if not errors and not warnings:
        print('CLEAN - no errors or warnings')
except Exception as ex:
    print('Parse error:', ex)
    print(txt[:2000])
"

